function verifyRenderPurity(componentFn, props) {
  const run1 = JSON.stringify(componentFn(props));
  const run2 = JSON.stringify(componentFn(props));

  return {
    isPure: run1 === run2,
    output: JSON.parse(run1)
  };
}
